  	$seleccion = $this->getRequestParameter('id_seleccion');
	$permiso = $this->getRequestParameter('permiso'); 	  	
  	$c = new Criteria();
	if($combo == 'series'){		
  			$c->add(SeriePeer::DEPENDENCIA_ID, $seleccion);
