  public function executeUpdate()
  {
    if (!$this->getRequestParameter('cliente_id'))
    {
      $cliente = new Cliente();
    }
	else
    {
      $cliente = ClientePeer::retrieveByPk($this->getRequestParameter('cliente_id'));
      $this->forward404Unless($cliente);
    }
    
    $cliente_anterior=$cliente->copy();
    
    $cliente->setClienteId($this->getRequestParameter('cliente_id'));
    $cliente->setFrecconsultaclienteId($this->getRequestParameter('frecconsultacliente_id') ? $this->getRequestParameter('frecconsultacliente_id') : null);
    $cliente->setSubserieId($this->getRequestParameter('subserie_id'));
    $cliente->setClienteestadoId(1);
    $cliente->setUnidconservadoraId($this->getRequestParameter('unidconservadora_id') ? $this->getRequestParameter('unidconservadora_id') : null);
    $cliente->setSoporteClienteId($this->getRequestParameter('soporte_cliente_id') ? $this->getRequestParameter('soporte_cliente_id') : null);
    $cliente->setCodigoCliente($this->getRequestParameter('codigo_cliente'));
    if ($this->getRequestParameter('fecha_apertura'))
    {      
      $cliente->setFechaApertura($this->getRequestParameter('fecha_apertura').date("G:i:s"));
    }else{
		$cliente->setFechaApertura(date("Y-m-d G:i:s"));
	}
    if ($this->getRequestParameter('fecha_cierre'))
    {      
      $cliente->setFechaCierre($this->getRequestParameter('fecha_cierre').date("G:i:s"));
    }
    $cliente->setNombreCliente($this->getRequestParameter('nombre_cliente'));
    $cliente->setContenido($this->getRequestParameter('contenido'));
    $cliente->setCreadoPorWeb($this->getRequestParameter('creado_por_web', true));
    $cliente->setUbicacion($this->getRequestParameter('ubicacion'));
    $cliente->setFolios($this->getRequestParameter('folios'));
    $cliente->setFechaCreacion(date("Y-m-d G:i:s"));
    $cliente->setNotas($this->getRequestParameter('notas'));
    if ($this->getRequestParameter('fecha_vencimiento'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('fecha_vencimiento'), $this->getUser()->getCulture());
      $cliente->setFechaVencimiento("$y-$m-$d");
    }
    $cliente->setVolumen($this->getRequestParameter('volumen'));
    if ($this->getRequestParameter('fecha_afiliacion'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('fecha_afiliacion'), $this->getUser()->getCulture());
      $cliente->setFechaAfiliacion("$y-$m-$d");
    }
    $cliente->setMarca(0);
    $cliente->save();
    //$this->guardarAuditoria($cliente_anterior,$cliente);
    
    $creador 		= $this->getRequestParameter('id_creador');
    $inventariador 	= $this->getRequestParameter('id_inventariador');
    $responsable	= $this->getRequestParameter('id_responsable');
    
    if($this->getRequestParameter('cliente_id') == ''){
     $this->setClienteUsuarios($creador,$inventariador,$responsable,$cliente->getClienteId());     
    }else{    	
	 $this->setClUserEdit($creador,$inventariador,$responsable,$cliente->getClienteId()); 	
	}
	if($cliente->getFechaVencimiento() == ''){ 
      $cliente->setFechaVencimiento($this->fechaVenceCliente($cliente->getClienteId()));
      $cliente->save();
    }
    return $this->redirect($this->getRequest()->getScriptName().'/cliente/show?cliente_id='.$cliente->getClienteId());
    //return $this->redirect($this->getRequest()->getScriptName().'/cliente/list');
  }
  
