  public function fechaVenceCliente($cliente_id)
  {
  	$cliente  = ClientePeer::retrieveByPK($cliente_id);
  	//$subserie = SubseriePeer::retrieveByPK($cliente->getSubserieId());
  	$fechaCierre  = $cliente->getFechaCierre();  	  	
  	if( $fechaCierre != ''){  			   	
	   	$fecha   = AddYears($fechaCierre,$cliente->getSubserie()->getAnosEnGestion());	   	
	}else{
		$fecha   = AddYears($fechaCierre,$cliente->getSubserie()->getAnosEnCentral());
	}
	return $fecha;
  }    
    
