    /**************************************************************************************************************/
    // CONSULTA FECHA APERTURA
	$fecha_apertura_inicial = $this->getRequestParameter('fecha_apertura');
	$fecha_apertura_final = $this->getRequestParameter('fecha_apertura_final');
	
	if($fecha_apertura_inicial != "" and $fecha_apertura_final == ""){
		$c->add(ClientePeer::FECHA_APERTURA, $fecha_apertura_inicial);
		$parametros .= "&fecha_apertura=".$fecha_apertura_inicial;		
	}elseif($fecha_apertura_inicial != "" and $fecha_apertura_final != ""){
		$c->add(ClientePeer::FECHA_APERTURA, $fecha_apertura_inicial, Criteria::GREATER_EQUAL);
		$c->addAnd(ClientePeer::FECHA_APERTURA, $fecha_apertura_final, Criteria::LESS_EQUAL);
		$parametros .= "&fecha_apertura=".$fecha_apertura_inicial;
		$parametros .= "&fecha_apertura_final=".$fecha_apertura_final;			
	}
	/**************************************************************************************************************/
	// CONSULTA FECHA CIERRE
	$fecha_cierre_inicial = $this->getRequestParameter('fecha_cierre');
	$fecha_cierre_final = $this->getRequestParameter('fecha_cierre_final');
	
	if($fecha_cierre_inicial != "" and $fecha_cierre_final == ""){
		$c->add(ClientePeer::FECHA_CIERRE, $fecha_cierre_inicial);
		$parametros .= "&fecha_cierre=".$fecha_cierre_inicial;		
	}elseif($fecha_cierre_inicial != "" and $fecha_cierre_final != ""){
		$c->add(ClientePeer::FECHA_CIERRE, $fecha_cierre_inicial, Criteria::GREATER_EQUAL);
		$c->addAnd(ClientePeer::FECHA_CIERRE, $fecha_cierre_final, Criteria::LESS_EQUAL);
		$parametros .= "&fecha_cierre=".$fecha_apertura_inicial;
		$parametros .= "&fecha_cierre_final=".$fecha_cierre_final;			
	}
	/**************************************************************************************************************/
	// CONSULTA FECHA VENCIMIENTO
	$fecha_vencimiento_inicial = $this->getRequestParameter('fechavencimiento');
	$fecha_vencimiento_final = $this->getRequestParameter('fecha_vencimiento_final');
	
	if($fecha_vencimiento_inicial != "" and $fecha_vencimiento_final == ""){
		$c->add(ClientePeer::FECHAVENCIMIENTO, $fecha_vencimiento_inicial);
		$parametros .= "&fechavencimiento=".$fecha_vencimiento_inicial;		
	}elseif($fecha_vencimiento_inicial != "" and $fecha_vencimiento_final != ""){
		$c->add(ClientePeer::FECHAVENCIMIENTO, $fecha_vencimiento_inicial, Criteria::GREATER_EQUAL);
		$c->addAnd(ClientePeer::FECHAVENCIMIENTO, $fecha_vencimiento_final, Criteria::LESS_EQUAL);
		$parametros .= "&fechavencimiento=".$fecha_vencimiento_inicial;
		$parametros .= "&fecha_vencimiento_final=".$fecha_vencimiento_final;			
	}
	/**************************************************************************************************************/
	// CONSULTA FECHA CREACION
	$fecha_creacion_inicial = $this->getRequestParameter('fecha_creacion_inicial');
	$fecha_creacion_final = $this->getRequestParameter('fecha_creacion_final');
	if($fecha_creacion_inicial != ""){
		if($fecha_creacion_final == ""){
			$fecha_creacion_final = $fecha_creacion_inicial;
		}
		$c->add(ClientePeer::FECHA_CREACION, $fecha_creacion_inicial.' 00:00:00', Criteria::GREATER_EQUAL);
		$c->addAnd(ClientePeer::FECHA_CREACION, $fecha_creacion_final.' 23:59:59', Criteria::LESS_EQUAL);
		$parametros .= "&fecha_creacion_inicial=".$fecha_creacion_inicial;
		$parametros .= "&fecha_creacion_final=".$fecha_creacion_final;		
	}
	/**************************************************************************************************************/
	// CONSULTA CREADO POR
	$creado_por = $this->getRequestParameter('id_creador');
	if($creado_por != ""){
		$c->addJoin(ClientePeer::CLIENTE_ID, ClUsuarioPeer::CLIENTE_ID);
		$c->add(ClUsuarioPeer::USUARIO_ID, $creado_por);
		$c->add(ClUsuarioPeer::ROL_CLUSUARIO_ID, 1);
		$parametros .= "&id_creador=".$creado_por;			
	}
	/**************************************************************************************************************/
	// CONSULTA INVENTARIADO POR
	$inventariado_por = $this->getRequestParameter('id_inventariador');
	if($inventariado_por != ""){
		$c->addJoin(ClientePeer::CLIENTE_ID, ClUsuarioPeer::CLIENTE_ID);
		$c->add(ClUsuarioPeer::USUARIO_ID, $creado_por);
		$c->add(ClUsuarioPeer::ROL_CLUSUARIO_ID, 2);
		$parametros .= "&id_inventariador=".$inventariado_por;			
	}
	/**************************************************************************************************************/
	// CONSULTA RESPONSABLE
	$responsable = $this->getRequestParameter('id_responsable');
	if($responsable != ""){
		$c->addJoin(ClientePeer::CLIENTE_ID, ClUsuarioPeer::CLIENTE_ID);
		$c->add(ClUsuarioPeer::USUARIO_ID, $creado_por);
		$c->add(ClUsuarioPeer::ROL_CLUSUARIO_ID, 3);
		$parametros .= "&id_responsable=".$responsable;			
	}
	/**************************************************************************************************************/
	$c->addDescendingOrderByColumn(ClientePeer::CLIENTE_ID);
	$pager = new sfPropelPager('Cliente', 10);
	$pager->setCriteria($c);        
	$pager->setPage($this->getRequestParameter('page', 1));
	$pager->init();
	$this->pager = $pager;
	$this->parametros = $parametros;	;		    
	/**************************************************************************************************************/
	if($this->getRequestParameter('accion')){
	  $marca = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	}else{
	  $marca = 0;	
	}
	if($this->getRequestParameter('accion') != 2){			  				
		foreach ($pager->getResults() as $resp) {
			$cliente = ClientePeer::retrieveByPk($resp->getClienteId());
			$cliente->setMarca($marca);
			$cliente->save();	  			       	    	
		}
	}else{
		$i = 1;							
		foreach ($pager->getResults() as $resp){			
			if($this->getRequestParameter('marca'.$i)? '1' : '0'){				
				$cliente = ClientePeer::retrieveByPk($resp->getClienteId());
				$cliente->setMarca($marca);
				$cliente->save();
			}else{				
				$cliente1 = ClientePeer::retrieveByPk($resp->getClienteId());
				$cliente1->setMarca(0);
				$cliente1->save();
			}
			$i++;
		}
	  $this->redirect('cliente/list?'.$parametros);	
	}			   		   	
  }
  
  public function executeMarcar()
  {
  	$marcar = 0;
  	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
  	$cliente = ClientePeer::retrieveByPK($this->getRequestParameter('cliente_id'));
  	if($cliente->getMarca() == 0 || $com_enviada->getMarca() != $usuariologuiado)
  	{
  		$marcar = $usuariologuiado;
  	}
  	$cliente->setMarca($marcar);
  	$cliente->save();
  }
  
