  public function setClienteUsuarios($rol_creador,$rol_inventa,$rol_respon , $clinte_id)
  {
  	/**************************************************************************************************/
	$usuario_cliente_crea  = new ClUsuario();
	$usuario_cliente_crea->setRolClusuarioId(1);
	$usuario_cliente_crea->setUsuarioId($rol_creador);
	$usuario_cliente_crea->setClienteId($clinte_id);
	$usuario_cliente_crea->save();
	/**************************************************************************************************/
	$usuario_cliente_inv  = new ClUsuario();
	$usuario_cliente_inv->setRolClusuarioId(2);
	$usuario_cliente_inv->setUsuarioId($rol_inventa);
	$usuario_cliente_inv->setClienteId($clinte_id);
	$usuario_cliente_inv->save();
	/**************************************************************************************************/
	$usuario_cliente_resp  = new ClUsuario();
	$usuario_cliente_resp->setRolClusuarioId(3);
	$usuario_cliente_resp->setUsuarioId($rol_respon);
	$usuario_cliente_resp->setClienteId($clinte_id);
	$usuario_cliente_resp->save(); 
	/**************************************************************************************************/
  }
  
  public function setClUserEdit($rol_creador,$rol_inventa,$rol_respon , $clinte_id)
  {
  	/**************************************************************************************************/
  	$c = new Criteria();
  	$c->add(ClUsuarioPeer::CLIENTE_ID,$clinte_id);
  	$c->add(ClUsuarioPeer::ROL_CLUSUARIO_ID,1);
  	$creador = ClUsuarioPeer::doSelectOne($c);
  	$creador->setUsuarioId($rol_creador);
  	$creador->save();
  	/**************************************************************************************************/
	$a = new Criteria();
  	$a->add(ClUsuarioPeer::CLIENTE_ID,$clinte_id);
  	$a->add(ClUsuarioPeer::ROL_CLUSUARIO_ID,2);
  	$inventariador = ClUsuarioPeer::doSelectOne($a);
  	$inventariador->setUsuarioId($rol_inventa);
  	$inventariador->save();
	/**************************************************************************************************/
	$b = new Criteria();
  	$b->add(ClUsuarioPeer::CLIENTE_ID,$clinte_id);
  	$b->add(ClUsuarioPeer::ROL_CLUSUARIO_ID,3);
  	$responsable = ClUsuarioPeer::doSelectOne($b);
  	$responsable->setUsuarioId($rol_respon);
  	$responsable->save();
	/**************************************************************************************************/	
  }
  
  public function executeDelete()
  {
    $cliente = ClientePeer::retrieveByPk($this->getRequestParameter('cliente_id'));

    $this->forward404Unless($cliente);

    $cliente->delete();

    return $this->redirect($this->getRequest()->getScriptName().'/cliente/list');
  }
}
